function tickerRelleno(tanda){
  const out=[];
  /* Sin partida (el menú de modos del arranque, donde G todavía es null) antes
     se devolvían las quince frases fijas de TICKER_BASE y la cinta no contaba
     nada más en toda la sesión. Ahora también ahí se inventan titulares. */
  if(!G||!G.clubes)return tickerRellenoMenu(tanda);
  const t9='t'+(tanda||0);   // el nº de tanda va DENTRO del hash: si no, cada vuelta inventaría lo mismo
  try{
    const cs=Object.values(G.clubes).filter(c=>c.div>0);
    const js=Object.values(G.jug);
    for(let i=0;i<14;i++){
      const t=TICKER_PLANTILLA[(hashStr('tk'+G.año+G.sem+t9+i))%TICKER_PLANTILLA.length];
      const c=cs[hashStr('c'+i+G.sem+t9)%cs.length];
      const j=js[hashStr('j'+i+G.sem+t9)%js.length];
      if(!c||!j)continue;
      out.push('<b>'+t[0]+'</b> '+esc(t[1]
        .replace('{club}',descensurar(c.nombre))
        .replace('{jug}',descensurar(j.nombre))
        .replace('{pais}',c.pais)
        .replace('{edad}',String(j.edad))
        .replace('{plata}',fmt$(Math.round(j.valor*1.4)))));
    }
  }catch(e){}
  return out.length?out:TICKER_BASE.slice();
