/* Clubes y futbolistas para cuando NO hay mundo generado. Se arma una sola vez
   y desde las tablas que ya existen en el archivo (DATA_P1/DATA_P2 para Chile,
   PAISES_LIGAS para el resto y los planteles de REALES para los nombres): ni un
   solo nombre escrito a mano. */
let __tkPool=null;
function tickerPool(){
  if(__tkPool)return __tkPool;
  const clubes=[],jugs=[];
  try{
    for(const d of DATA_P1)clubes.push({nombre:descensurar(d[0]),pais:'CHI'});
    for(const d of DATA_P2)clubes.push({nombre:descensurar(d[0]),pais:'CHI'});
    for(const p in PAISES_LIGAS)for(const d of PAISES_LIGAS[p].clubes)clubes.push({nombre:descensurar(d[0]),pais:p});
    for(const k in REALES)for(const s of REALES[k]){
      const f=String(s).split('|');            // "Nombre|PUESTO|EDAD|MEDIA|PAÍS"
      if(f.length>=4)jugs.push({nombre:f[0],edad:+f[2]||24,media:+f[3]||70});
    }
  }catch(e){}
  __tkPool={clubes,jugs};
  return __tkPool;
}
function tickerRellenoMenu(tanda){
  const P=tickerPool();
  if(!P.clubes.length||!P.jugs.length)return TICKER_BASE.slice();
  const t9='m'+(tanda||0);
  const out=[];
  try{
    for(let i=0;i<14;i++){
      const t=TICKER_PLANTILLA[hashStr('tp'+t9+i)%TICKER_PLANTILLA.length];
      const c=P.clubes[hashStr('tc'+t9+i)%P.clubes.length];
      const j=P.jugs[hashStr('tj'+t9+i)%P.jugs.length];
      /* La cifra sale de la MISMA curva que tasa a los jugadores en partida
         (calcEco), no de un número puesto a ojo: si mañana se mueve la economía,
         los titulares del menú se mueven con ella. */
      const val=VALOR_PIVOTE*Math.pow(CURVA_JUG,j.media-OVR_PIVOTE)*factorEdad({edad:j.edad,ovr:j.media,pot:j.media});
      out.push('<b>'+t[0]+'</b> '+esc(t[1]
        .replace('{club}',c.nombre)
        .replace('{jug}',j.nombre)
        .replace('{pais}',c.pais)
        .replace('{edad}',String(j.edad))
        .replace('{plata}',fmt$(Math.round(val*1.4)))));
    }
    /* Y unas cuantas del mundo genérico, para que no todo sean fichajes */
    for(let i=0;i<4;i++)out.push(TICKER_BASE[hashStr('tb'+t9+i)%TICKER_BASE.length]);
  }catch(e){}
  return out.length?out:TICKER_BASE.slice();
}

