/* --- La cinta por dentro ---
   Por qué ya no la mueve el CSS: @keyframes sólo sabe volver al principio, así
   que al acabar la vuelta reaparecía el mismo HTML y siempre se leían los mismos
   titulares (y como la tira llevaba la tanda pegada dos veces, se repetían dos
   veces por vuelta). Aquí la cinta es una COLA: el titular que sale por la
   izquierda se tira y por la derecha entra uno que no se había visto, así que el
   desplazamiento no se corta jamás y no hay tanda que repetir. */
const TICKER_PPS=74;      // píxeles por segundo. Antes la velocidad la decidía el largo del texto: 52 s fijos para una tira enorme salían a ~300 px/s, ilegibles
let __tkCola=[];          // titulares pendientes de entrar por la derecha
let __tkTanda=0;          // nº de tanda; entra en la semilla para que cada una salga distinta
let __tkGen=0;            // cada arranque invalida el bucle anterior
function tickerSiguiente(){
  if(!__tkCola.length)__tkCola=tickerLote(++__tkTanda);
  if(!__tkCola.length)__tkCola=TICKER_BASE.slice();
  return __tkCola.shift();
}
function arrancarTicker(){
  const tk=document.querySelector('.ticker');
  if(!tk)return;
  const via=tk.querySelector('.tickerIn');
  if(!via)return;
  const mio=++__tkGen;
  let off=tk.clientWidth*0.42;   // el primer titular entra donde entraba con el padding-left:42% de antes
  let ult=0;
  const paso=(t)=>{
    if(mio!==__tkGen||!document.body.contains(via))return;   // se repintó la pantalla: este bucle se apaga solo
    const dt=ult?Math.min(0.05,(t-ult)/1000):0;              // tope de 50 ms: al volver de otra pestaña la cinta no pega un salto
    ult=t;
    if(!tk.matches(':hover'))off-=TICKER_PPS*dt;             // la pausa al pasar el ratón, que antes hacía el CSS
    /* Tira el titular que ya cruzó el borde izquierdo y compensa el hueco que
       deja con lo que realmente se corren los demás, no con un número copiado
       del CSS: si mañana cambian los márgenes, esto sigue cuadrando. */
    const pri=via.firstElementChild;
    if(pri&&off+pri.offsetLeft+pri.offsetWidth<0){
      const seg=via.children[1];
      const antes=seg?seg.offsetLeft:0;
      via.removeChild(pri);
      if(seg)off+=antes-seg.offsetLeft;
    }
    /* Rellena por la derecha hasta pasarse del borde: siempre hay un titular
       nuevo esperando fuera de pantalla, así que no existe el hueco del final
       de la tanda ni el salto al volver a empezar. */
    for(let n=0;n<24&&off+via.offsetWidth<tk.clientWidth+160;n++){
      const s=document.createElement('span');
      s.innerHTML=tickerSiguiente();
      via.appendChild(s);
    }
    via.style.transform='translateX('+off.toFixed(1)+'px)';
    requestAnimationFrame(paso);
  };
  requestAnimationFrame(paso);
}
function tickerHTML(){
  /* La cinta nace vacía y la llena arrancarTicker(). El setTimeout no es
     capricho: quien llama mete este HTML con innerHTML, así que en este momento
     todavía no hay nada en el DOM a lo que engancharse; el timeout corre justo
     después de esa asignación. Así vale para cualquier pantalla que pinte la
     cinta sin tener que acordarse de arrancarla a mano. */
  __tkCola=[];              // la próxima tanda se arma con el estado de AHORA, no con el de la pantalla anterior
  setTimeout(arrancarTicker,0);
  return `<div class="ticker"><div class="tickerIn"></div></div>`;
}
